import{_ as a,c as i,o as n,ag as r}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Ham-radio","description":"","frontmatter":{"title":"Ham-radio"},"headers":[],"relativePath":"radio/ham-radio.md","filePath":"radio/ham-radio.md","lastUpdated":null}'),o={name:"radio/ham-radio.md"};function t(s,e,l,d,c,h){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ham-radio" tabindex="-1">Ham-radio <a class="header-anchor" href="#ham-radio" aria-label="Permalink to &quot;Ham-radio&quot;">​</a></h1><h2 id="ham-radio-resources" tabindex="-1">Ham Radio Resources <a class="header-anchor" href="#ham-radio-resources" aria-label="Permalink to &quot;Ham Radio Resources&quot;">​</a></h2><p>return to <a href="/general/certifications.html">page</a></p><h3 id="introduction-to-ham-radio" tabindex="-1">Introduction to Ham Radio <a class="header-anchor" href="#introduction-to-ham-radio" aria-label="Permalink to &quot;Introduction to Ham Radio&quot;">​</a></h3><p>Ham radio, also known as amateur radio, is a popular hobby and service that brings people, electronics, and communication together. People use ham radio to communicate across town, around the world, or even into space, all without the Internet or cell phones. It’s fun, social, educational, and can be a lifeline during times of need.</p><h3 id="getting-licensed" tabindex="-1">Getting Licensed <a class="header-anchor" href="#getting-licensed" aria-label="Permalink to &quot;Getting Licensed&quot;">​</a></h3><p>Before you can transmit on ham radio frequencies, you need to be licensed. In the United States, the Federal Communications Commission (FCC) issues these licenses. US licenses are valid for 10 years before renewal, and anyone may hold one except representatives of a foreign government. There are three license classes:</p><ul><li><p><strong>Technician License</strong>: This is the entry-level license. It grants access to all Amateur Radio frequencies above 30 megahertz, allowing communication locally and within North America. It requires passing a 35-question examination.</p></li><li><p><strong>General License</strong>: This license grants some operating privileges on all Amateur Radio bands and all operating modes, opening the door to worldwide communications. Requires passing a 35-question examination and having passed the Technician written examination.</p></li><li><p><strong>Amateur Extra License</strong>: This is the highest level of license, offering all available U.S. Amateur Radio operating privileges on all bands and all modes. It requires passing a thorough 50 question examination and having passed all previous license class written examinations.</p></li></ul><p>For more detailed information, the American Radio Relay League (ARRL) provides resources at <a href="https://www.arrl.org/getting-licensed" target="_blank" rel="noreferrer">https://www.arrl.org/getting-licensed</a>.</p><h3 id="study-resources" tabindex="-1">Study Resources <a class="header-anchor" href="#study-resources" aria-label="Permalink to &quot;Study Resources&quot;">​</a></h3><p>To prepare for your licensing exam, numerous resources are available:</p><ul><li><p>Online study guides like <a href="http://ham-cram.com/member-lounge/technician-study.php" target="_blank" rel="noreferrer">Ham Cram</a> and <a href="https://www.arrl.org/exam-practice" target="_blank" rel="noreferrer">ARRL’s exam practice</a>.</p></li><li><p>Anki Flashcards for efficient memorization of exam topics:</p></li><li><p>&#39; <a href="https://ankiweb.net/shared/info/1989339803" target="_blank" rel="noreferrer">US Amateur Radio - Technician (valid July 2022 - June 2026)</a></p></li><li><p>&#39; <a href="https://ankiweb.net/shared/info/817192394" target="_blank" rel="noreferrer">Amateur Radio Extra Exam 2020-2024 Flash Cards</a></p></li></ul><h3 id="training-opportunities" tabindex="-1">Training Opportunities <a class="header-anchor" href="#training-opportunities" aria-label="Permalink to &quot;Training Opportunities&quot;">​</a></h3><p>Local clubs and online communities often offer classes and study sessions for aspiring ham radio operators. - <a href="/general/flnc.html">Liberty</a> has options for getting trained and certified</p><h3 id="finding-exam-sessions" tabindex="-1">Finding Exam Sessions <a class="header-anchor" href="#finding-exam-sessions" aria-label="Permalink to &quot;Finding Exam Sessions&quot;">​</a></h3><p>ARRL provides resources to find in-person ham radio exam locations in your area or schedule an online exam. Online and in-person tests are given regularly. For more information, visit <a href="https://www.arrl.org/find-an-amateur-radio-license-exam-session" target="_blank" rel="noreferrer">Find an Amateur Radio License Exam Session</a>.</p><h3 id="joining-the-ham-radio-community" tabindex="-1">Joining the Ham Radio Community <a class="header-anchor" href="#joining-the-ham-radio-community" aria-label="Permalink to &quot;Joining the Ham Radio Community&quot;">​</a></h3><p>Once licensed, new operators can join local clubs, participate in contests, and attend hamfests and conventions. The ARRL website offers a club search tool and information on upcoming events. Engaging with the community is a great way to learn, make new friends, and get the most out of your ham radio experience.</p><h3 id="contests-and-awards" tabindex="-1">Contests and Awards <a class="header-anchor" href="#contests-and-awards" aria-label="Permalink to &quot;Contests and Awards&quot;">​</a></h3><p>Ham radio offers numerous contests and awards for operators of all levels. These activities can enhance your operating skills, provide opportunities to test your station setup, and offer a fun way to engage with the global ham radio community.</p>',20)])])}const p=a(o,[["render",t]]);export{u as __pageData,p as default};
